// Generates src/lib-bundle.ts — a map of `lib.*.d.ts` filename → contents
// for the subset of TypeScript's bundled libs the typecheck wasm needs.
//
// Why pre-generate instead of importing each lib file at runtime?
//   - The typescript package's lib files are regular `.d.ts` text on
//     disk. esbuild's `text` loader can pull them in, but doing it by
//     glob would add a build-config step. A small generator script
//     keeps the typecheck JS source uncluttered.
//
// Why filter `dom` and `webworker` out?
//   - Particles run server-side; DOM and WebWorker types are dead
//     weight (the lib.dom.d.ts file alone is ~600 KB). Skipping them
//     keeps the wasm artifact lean.
//
// Run from the typecheck component directory:
//   node build-lib-bundle.mjs
//
// Driven by the typecheck Makefile target.

import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const libDir = "node_modules/typescript/lib";

const files = readdirSync(libDir).filter((f) => {
  if (!f.startsWith("lib.") || !f.endsWith(".d.ts")) return false;
  // Particles don't run in browsers; cut DOM + webworker.
  if (f.includes("dom")) return false;
  if (f.includes("webworker")) return false;
  return true;
});

const map = {};
let total = 0;
for (const f of files.sort()) {
  const data = readFileSync(join(libDir, f), "utf8");
  map[f] = data;
  total += data.length;
}

const out = `// Generated by build-lib-bundle.mjs. DO NOT EDIT.
// Subset of TypeScript's bundled lib.*.d.ts files (DOM/WebWorker
// excluded). Used by typecheck.ts to back a custom CompilerHost so
// the type checker has access to ECMAScript built-ins without needing
// host filesystem access at runtime.
//
// eslint-disable
export const TS_LIB_FILES: Record<string, string> = ${JSON.stringify(map)};
`;

mkdirSync("src", { recursive: true });
writeFileSync("src/lib-bundle.ts", out);

console.log(
  `wrote src/lib-bundle.ts: ${files.length} libs, ${(total / 1024).toFixed(0)} KB total`,
);
